with dim_totals as (select p.channel, p.status as order_status, src.status as shipment_status, count(*) as num_rows, sum(src.cost) as total_cost, grouping_id() as grouping_level from shipments src left join orders p on src.order_id = p.id group by cube (p.channel, p.status, src.status)) select channel, order_status, shipment_status, total_cost, grouping_level, case when shipment_status rlike '^(LOST|RETURNED)$' then 'EXTENDED' else 'PRIORITY' end as shipment_status_zone from dim_totals order by channel
